// Command darksafe is the 零信任身份与授权决策平台 entry point.
package main

import (
	"fmt"
	"io"
	"os"
)

func main() {
	os.Exit(dispatch(os.Args, os.Stdout, os.Stderr))
}

// dispatch selects one subcommand from the full argument vector
// (args[0] is the program name). With no arguments it runs the demo,
// preserving the original no-argument behavior.
func dispatch(args []string, stdout, stderr io.Writer) int {
	command := "demo"
	if len(args) > 1 {
		command = args[1]
	}
	switch command {
	case "review":
		return runReview(args[1:], stdout, stderr)
	case "demo":
		runDemo(stdout)
		return 0
	case "version":
		fmt.Fprintln(stdout, "darksafe 0.1.0")
		return 0
	case "help", "-h", "--help":
		usage(stdout)
		return 0
	default:
		fmt.Fprintf(stderr, "unknown command %q\n", command)
		usage(stderr)
		return 2
	}
}

func usage(w io.Writer) {
	fmt.Fprintln(w, "usage: darksafe [demo|version|review|help]")
	fmt.Fprintln(w, "")
	fmt.Fprintln(w, "commands:")
	fmt.Fprintln(w, "  demo      run the built-in no-argument demonstration (default)")
	fmt.Fprintln(w, "  version   print the version")
	fmt.Fprintln(w, "  review    review one archived access decision offline;")
	fmt.Fprintln(w, "            run `darksafe review --help` for its arguments and an example")
	fmt.Fprintln(w, "  help      show this help")
}

// The review subcommand re-evaluates one decision preserved in an audit
// archive after the service instance that decided it has ended. It never
// talks to a running service and never creates or restores a Store: the
// decision is recomputed purely from the saved record's request, the
// historical policy version carried in records before it, and a checkpoint
// the caller retained separately from the archive.
package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

// Exit codes for the review command:
//
//   - 0: a full review was produced, including a legitimate archive whose
//     original and recomputed decisions disagree.
//   - 2: the invocation itself is wrong (missing/invalid arguments, the
//     archive file cannot be read).
//   - 1: the material or target cannot support a review (an invalid or
//     chain-broken archive, a missing or non-decision target, a historical
//     policy version that cannot be obtained).
const (
	reviewExitOK     = 0
	reviewExitFailed = 1
	reviewExitUsage  = 2
)

// reviewInputs holds everything the review command needs from the caller.
type reviewInputs struct {
	archivePath string
	org         string
	seq         int
	endSeq      int
	fingerprint string
}

func reviewHelp(w io.Writer) {
	fmt.Fprint(w, `usage: darksafe review --archive FILE --org ORG --seq N \
                      --end-seq N --fingerprint HEX

Review one access decision saved in an audit archive, long after the
service instance that made the decision has ended. No running service is
contacted and no policy store is created or restored; the decision is
recomputed offline from the archived material alone. The archived decision
is never re-submitted as a new access request.

Required inputs:
  --archive FILE       path to the audit archive written by
                       EncodeAuditArchive (the complete export, not a
                       subject-filtered page or a fragment)
  --org ORG            organization name the archive belongs to; it must
                       match the organization bound into the records
  --seq N              positive sequence number of the decision record to
                       review (organization-local, starting at 1)
  --end-seq N          end sequence of the checkpoint retained separately
                       from the archive (0 for an organization with no
                       records); must not be negative
  --fingerprint HEX    checkpoint fingerprint retained separately from the
                       archive (64 hexadecimal SHA-256 characters)

The checkpoint carried inside the archive is informational only: validation
always uses --end-seq/--fingerprint supplied here. Even when --seq points at
an early record, every archived record is checked; a corrupted or missing
later record, or any mismatch with the retained checkpoint, fails the whole
review with no partial output.

The request is replayed strictly against the policy version the recorded
decision actually used; later publishes or rollbacks present in the archive
are never substituted. A chain that is valid but whose original and
recomputed decisions disagree is still printed in full and exits 0; the
disagreement is shown explicitly rather than reported as file damage.

Strings may contain spaces, control characters or non-UTF-8 bytes; output
quoting keeps different raw bytes distinguishable. This command only reads
the named archive: it neither rewrites it nor appends audit records.

Exit codes: 0 review complete (decisions may disagree), 1 archive or target
invalid / historical version unavailable, 2 bad arguments or unreadable
file.

Example:
  (materials produced by examples/offline_review; seq 1 is the
  policy publish record, seq 2 is the read decision being reviewed)
  darksafe review --archive acme-factory.audit \
      --org 'acme factory' --seq 2 --end-seq 2 \
      --fingerprint 04b274dbb4cf039bbb4b78f5ee5aae03278d2c34833fe87fecb13ade51ef5299
`)
}

// parseReviewArgs parses review arguments. flags is an injectable args slice
// so tests can drive the command directly. The first element of args is the
// subcommand name ("review"). --help/-h/-help set wantHelp.
func parseReviewArgs(args []string) (in reviewInputs, wantHelp bool, err error) {
	haveSeq, haveEndSeq := false, false
	for i := 1; i < len(args); i++ {
		arg := args[i]
		value := ""
		hasValue := false
		switch {
		case arg == "--help" || arg == "-h" || arg == "-help":
			return reviewInputs{}, true, nil
		case len(arg) > 2 && arg[:2] == "--":
			// Accept both --flag value and --flag=value.
			if eq := strings.IndexByte(arg, '='); eq >= 0 {
				value = arg[eq+1:]
				hasValue = true
				arg = arg[:eq]
			}
		default:
			return reviewInputs{}, false, fmt.Errorf("unexpected argument %q", arg)
		}

		take := func() (string, error) {
			if hasValue {
				return value, nil
			}
			if i+1 >= len(args) {
				return "", fmt.Errorf("flag %s requires a value", arg)
			}
			i++
			return args[i], nil
		}

		switch arg {
		case "--archive":
			v, err := take()
			if err != nil {
				return reviewInputs{}, false, err
			}
			in.archivePath = v
		case "--org":
			v, err := take()
			if err != nil {
				return reviewInputs{}, false, err
			}
			in.org = v
		case "--seq":
			v, err := take()
			if err != nil {
				return reviewInputs{}, false, err
			}
			n, perr := strconv.Atoi(v)
			if perr != nil {
				return reviewInputs{}, false, fmt.Errorf("--seq must be an integer, got %q", v)
			}
			in.seq = n
			haveSeq = true
		case "--end-seq":
			v, err := take()
			if err != nil {
				return reviewInputs{}, false, err
			}
			n, perr := strconv.Atoi(v)
			if perr != nil {
				return reviewInputs{}, false, fmt.Errorf("--end-seq must be an integer, got %q", v)
			}
			in.endSeq = n
			haveEndSeq = true
		case "--fingerprint":
			v, err := take()
			if err != nil {
				return reviewInputs{}, false, err
			}
			in.fingerprint = v
		default:
			return reviewInputs{}, false, fmt.Errorf("unknown review flag %q", arg)
		}
	}

	if in.archivePath == "" {
		return reviewInputs{}, false, errors.New("--archive is required")
	}
	if in.org == "" {
		return reviewInputs{}, false, errors.New("--org is required")
	}
	if !haveSeq {
		return reviewInputs{}, false, errors.New("--seq is required")
	}
	if in.seq <= 0 {
		return reviewInputs{}, false, fmt.Errorf("--seq must be a positive integer, got %d", in.seq)
	}
	if !haveEndSeq {
		return reviewInputs{}, false, errors.New("--end-seq is required")
	}
	if in.endSeq < 0 {
		return reviewInputs{}, false, fmt.Errorf("--end-seq must not be negative, got %d", in.endSeq)
	}
	if in.fingerprint == "" {
		return reviewInputs{}, false, errors.New("--fingerprint is required")
	}
	return in, false, nil
}

// runReview executes one offline review and returns the process exit code.
// stdout/stderr are injectable so the command stays testable; args is the
// full argument vector including the leading "review".
func runReview(args []string, stdout, stderr io.Writer) int {
	in, wantHelp, err := parseReviewArgs(args)
	if wantHelp {
		reviewHelp(stdout)
		return reviewExitOK
	}
	if err != nil {
		fmt.Fprintf(stderr, "review: %s\n", err)
		return reviewExitUsage
	}

	archive, err := os.ReadFile(in.archivePath)
	if err != nil {
		fmt.Fprintf(stderr, "review: cannot read archive %q: %v\n", in.archivePath, err)
		return reviewExitUsage
	}

	cp := darksafe.Checkpoint{Org: in.org, EndSeq: in.endSeq, Fingerprint: in.fingerprint}
	records, err := darksafe.DecodeAuditArchive(archive, in.org, cp)
	if err != nil {
		fmt.Fprintf(stderr, "review: archive validation failed: %v\n", err)
		return reviewExitFailed
	}
	review, err := darksafe.RecheckDecisionOffline(in.org, records, cp, in.seq)
	if err != nil {
		fmt.Fprintf(stderr, "review: %v\n", err)
		return reviewExitFailed
	}

	printReview(stdout, review)
	return reviewExitOK
}

// printReview renders the target sequence, both full decisions and the
// consistency verdict. Every potentially non-UTF-8 string is emitted with
// %q (Go quoting): a lone 0xFF renders as "\xff", 0xFE as "\xfe" and a real
// U+FFFD as "�", so distinct raw bytes never collapse onto one glyph.
func printReview(w io.Writer, r darksafe.OfflineDecisionReview) {
	fmt.Fprintf(w, "target sequence: %d\n", r.Seq)
	fmt.Fprintln(w, "original decision:")
	printDecision(w, r.Original)
	fmt.Fprintln(w, "recomputed decision:")
	printDecision(w, r.Recomputed)
	if r.Consistent {
		fmt.Fprintln(w, "consistent: yes")
	} else {
		fmt.Fprintln(w, "consistent: no (original and recomputed decisions differ)")
	}
}

func printDecision(w io.Writer, d darksafe.Decision) {
	fmt.Fprintf(w, "  allowed: %v\n", d.Allowed)
	fmt.Fprintf(w, "  reason: %q\n", d.Reason)
	fmt.Fprintf(w, "  matched policies: %s\n", formatMatched(d.Matched))
	fmt.Fprintf(w, "  policy version: %d\n", d.Version)
}

// formatMatched quotes each matched policy identifier byte-for-byte. A nil
// and an empty list mean the same set of hits but keep distinguishable
// spellings, mirroring the library's own nil-versus-empty preservation.
func formatMatched(matched []string) string {
	if matched == nil {
		return "[]"
	}
	out := "["
	for i, id := range matched {
		if i > 0 {
			out += ", "
		}
		out += strconv.Quote(id)
	}
	return out + "]"
}

// This file holds the shared core of single-decision review. The online
// Store.RecheckDecision and the store-free RecheckDecisionOffline acquire
// their material differently — one reads an organization's live history
// and version snapshots, the other a chain-validated export paired with its
// separately retained checkpoint — but once the recorded request and the
// version it actually used are in hand, both replay the exact same
// judgment. That judgment lives only here so the two entry points can never
// drift on version-zero handling, envelope rejection order, or how a
// historical policy set is evaluated.
package darksafe

// replayStatus reports whether replayRecordedDecision produced a decision
// or why the declared version could not be replayed.
type replayStatus int

const (
	// replayDecided means a Decision was recomputed.
	replayDecided replayStatus = iota
	// replayVersionAbsent means content for the declared version exists
	// nowhere in the reviewer's material.
	replayVersionAbsent
	// replayVersionAfterTarget means the version's content exists, but only
	// in a policy change record positioned after the reviewed decision.
	// Online material never yields this: live version snapshots carry no
	// position relative to audit records.
	replayVersionAfterTarget
)

// versionPolicies is one resolver verdict: either the detached full policy
// set of the requested version, or a status explaining why it is unusable.
type versionPolicies struct {
	policies []Policy
	status   replayStatus
}

// resolveVersionPolicies supplies the full content of a non-zero version
// named by a reviewed decision. Implementations are responsible for
// detaching the returned policies from any state or input material.
type resolveVersionPolicies func(version int) versionPolicies

// replayRecordedDecision re-judges a recorded request against the version
// the record declares it actually used. Later publishes or rollbacks are
// never substituted for that version.
//
// A version-0 record first replays the envelope rejections in their fixed
// order (missing organizations and identifiers, empty action, organization
// mismatch, illegal scope, disabled subject); a request that passes is the
// "organization has no published version" denial.
//
// For a non-zero record the version is resolved before any request rule is
// applied: a missing, or only-later, version is an error the caller turns
// into ErrVersionNotFound and must never be masked by an envelope denial,
// even for a disabled subject. Once the version is in hand, the same
// envelope checks run before policy evaluation, so a rejection reports
// version 0 with no matched policies regardless of what the version
// contains. Evaluation itself is the historical policy set only: deny
// overrides allow, matched identifiers are sorted, resource restrictions
// narrow rather than replace scope matching, and subject roles never stand
// in for an organization policy.
func replayRecordedDecision(org string, req OrgRequest, version int, resolve resolveVersionPolicies) (Decision, replayStatus) {
	if version == 0 {
		// The original evaluation used no published version: replay the
		// envelope rejections exactly, in their recorded order, then the
		// not-yet-published denial.
		if d, ok := checkRequest(org, req); !ok {
			return d, replayDecided
		}
		return Decision{Allowed: false, Reason: "organization has no published version"}, replayDecided
	}
	// Resolve the version first. A request the envelope would reject must
	// not turn a missing or later-only declared version into an ordinary
	// denial.
	resolved := resolve(version)
	if resolved.status != replayDecided {
		return Decision{}, resolved.status
	}
	// The version exists as claimed, but chain integrity does not imply the
	// request was admissible: re-run the same envelope checks the online
	// decision runs before any policy is consulted. A rejection here
	// evaluates no policies, hence version 0 and no matches, even when the
	// version holds a fully matching allow policy.
	if d, ok := checkRequest(org, req); !ok {
		return d, replayDecided
	}
	return evaluate(req, resolved.policies, version), replayDecided
}

// This file implements offline review of a single audited decision. It
// works solely from exported audit material: the complete record export,
// the separately retained checkpoint, and a target sequence. No Store is
// created or restored, so an organization can confirm why an access was
// allowed or denied long after the service instance that decided it has
// ended.
//
// The complete input must first validate as an audit chain. The policy
// version a decision actually used is recovered exclusively from policy
// change records preceding that decision within the same organization's
// export; later publishes or rollbacks, and a wider later export, cannot
// change the recomputed result.
package darksafe

import "fmt"

// OfflineDecisionReview compares the decision stored in an audited record
// with a decision recomputed purely from the exported material.
type OfflineDecisionReview struct {
	// Seq is the reviewed decision record's sequence.
	Seq int
	// Original is the decision preserved in the audited record.
	Original Decision
	// Recomputed is the decision evaluated again offline from the saved
	// request and the policy version it originally used.
	Recomputed Decision
	// Consistent reports whether both decisions agree on every field
	// (allowance, reason, matched policies and version), treating a nil
	// matched list and an empty matched list as the same.
	Consistent bool
}

// RecheckDecisionOffline re-evaluates one decision record offline. org is
// the organization name, records is its complete export starting at
// sequence 1 (a valid prefix is sufficient when paired with its own
// checkpoint), cp is the separately saved checkpoint, and seq identifies
// the decision record to review. The call is read-only: it neither mutates
// the supplied material nor appends audit records, and the returned
// decisions are detached from the input slices.
//
// The entire export is chain-validated before any result is produced;
// tampering anywhere, including in records after the target, fails the
// review. Distinguishable errors follow the other audit entry points:
// ErrMissingOrganization for an empty organization, ErrAuditNotFound for a
// non-positive or absent target sequence, and ErrAuditNotADecision when the
// target is a policy change record. When the saved decision names a
// policy version whose full content has no change record before the
// target, ErrVersionNotFound is returned; a newer version is never
// substituted, and a request the envelope would reject never masks the
// missing version.
//
// The fingerprint only proves the material matches its checkpoint; it
// cannot stand in for evaluating the request itself. So even when the
// declared version exists and carries an otherwise matching allow policy,
// the recomputation enforces the same request rules as the online
// decision: a disabled subject, an organization mismatch, a missing
// subject or resource organization or identifier, an empty action, and an
// illegal resource scope all deny, with the same reasons and precedence as
// Decide. Such a rejection uses no policies, so the recomputed decision
// reports version 0 with no matched policies; it is then compared field by
// field with the preserved original and may come back inconsistent.
func RecheckDecisionOffline(org string, records []AuditRecord, cp Checkpoint, seq int) (OfflineDecisionReview, error) {
	if org == "" {
		return OfflineDecisionReview{}, ErrMissingOrganization
	}
	// Validate the whole export first. A subject-filtered page, a fragment
	// missing the beginning, or a checkpoint that does not pin the records
	// all fail here, as does any corruption after the target.
	if err := VerifyAudit(org, records, cp); err != nil {
		return OfflineDecisionReview{}, err
	}
	if seq < 1 {
		return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
	}
	if seq > len(records) {
		return OfflineDecisionReview{}, fmt.Errorf("%w: export ends at %d, no sequence %d", ErrAuditNotFound, len(records), seq)
	}
	rec := &records[seq-1]
	if rec.Kind != AuditDecision || rec.Decision == nil {
		return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
	}

	original := cloneDecisionValue(rec.Decision.Decision)
	req := rec.Decision.Request
	// Detach the request list by non-nil rather than by length: a non-nil
	// empty role list with spare capacity must not be shared back with the
	// caller's material, even though evaluation never reads any element.
	req.Subject.Roles = cloneStrings(req.Subject.Roles)
	version := original.Version

	// The version's full content must travel in a same-organization policy
	// change record positioned before the decision. The replay core resolves
	// the version before replaying any request rule, so a request the
	// envelope rejects cannot mask a missing or later-only version.
	resolve := func(want int) versionPolicies {
		if policies, found := policiesBefore(records, seq-1, want); found {
			return versionPolicies{policies: policies}
		}
		if _, later := policiesBefore(records, len(records), want); later {
			return versionPolicies{status: replayVersionAfterTarget}
		}
		return versionPolicies{status: replayVersionAbsent}
	}
	recomputed, status := replayRecordedDecision(org, req, version, resolve)
	switch status {
	case replayVersionAfterTarget:
		return OfflineDecisionReview{}, fmt.Errorf(
			"%w: decision at sequence %d used version %d, whose change record appears only after it",
			ErrVersionNotFound, seq, version)
	case replayVersionAbsent:
		return OfflineDecisionReview{}, fmt.Errorf(
			"%w: decision at sequence %d used version %d, which has no policy change record in the export",
			ErrVersionNotFound, seq, version)
	}

	return OfflineDecisionReview{
		Seq:        seq,
		Original:   original,
		Recomputed: recomputed,
		Consistent: decisionsEqual(original, recomputed),
	}, nil
}

// policiesBefore searches records[:limit] for the policy change record that
// published version and returns a detached copy of its full content. The
// gapless chain validation guarantees records are in sequence order.
func policiesBefore(records []AuditRecord, limit, version int) ([]Policy, bool) {
	for i := 0; i < limit; i++ {
		r := &records[i]
		if r.Kind != AuditPolicyChange || r.Change == nil {
			continue
		}
		if r.Change.Version == version {
			return append([]Policy(nil), r.Change.Policies...), true
		}
	}
	return nil, false
}

// cloneDecisionValue returns a decision detached from the input's matched
// slice. The list is detached whenever it is non-nil, including a non-nil
// empty list that still has spare capacity, so an append by one receiver
// can never reach another copy.
func cloneDecisionValue(d Decision) Decision {
	d.Matched = cloneStrings(d.Matched)
	return d
}

// decisionsEqual compares every decision field. A nil matched list and an
// empty matched list describe the same set of hits.
func decisionsEqual(a, b Decision) bool {
	if a.Allowed != b.Allowed || a.Reason != b.Reason || a.Version != b.Version {
		return false
	}
	if len(a.Matched) == 0 && len(b.Matched) == 0 {
		return true
	}
	if len(a.Matched) != len(b.Matched) {
		return false
	}
	for i := range a.Matched {
		if a.Matched[i] != b.Matched[i] {
			return false
		}
	}
	return true
}

// This file is the single definition of which fields a DecisionRecord
// carries for every audit-side treatment of decision content: the
// fingerprint's raw canonical encoder, the valid-UTF-8 test that chooses
// between the JSON and raw fingerprint families, the archive writer and
// reader, and the detaching copy that keeps stored records independent of
// caller slices. Each of those walks the one table below instead of naming
// the fields itself, so the fields and their order mean the same thing
// everywhere. Adding or changing a decision field here reaches
// fingerprinting, the UTF-8 decision, archiving, unarchiving and cloning at
// once; no audit path can keep a stale list of its own.
//
// The table order is part of the wire and fingerprint contract: it is the
// historical decision field order — the two organization names, the subject,
// the resource, the action, then the decision itself — and the archive
// mirrors it field for field. Authorization itself (org.go) is intentionally
// not driven from this table: Roles participates here as a saved request
// field even though org policy evaluation never matches on it.
package darksafe

import "unicode/utf8"

// decisionFieldKind says how one DecisionRecord field participates in
// fingerprinting and archiving.
type decisionFieldKind int

const (
	// decisionFieldString is a string field written from its exact bytes by
	// both the fingerprint encoder and the archive.
	decisionFieldString decisionFieldKind = iota
	// decisionFieldStringList is a string slice whose nil-versus-empty
	// shape and element order are preserved explicitly by both encoders.
	decisionFieldStringList
	// decisionFieldBool is a boolean field. It has no UTF-8 representation,
	// so the valid-UTF-8 scan skips it while both encoders write it.
	decisionFieldBool
	// decisionFieldInt is a non-negative integer field (the policy version
	// the decision used). It has no UTF-8 representation either.
	decisionFieldInt
)

// decisionFieldSpec locates one DecisionRecord leaf field. The accessors
// used depend on the kind: string fields use getString/setString, list
// fields getList/setList, booleans getBool/setBool and integers
// getInt/setInt. A field appears in decisionFields exactly once, and that
// entry is the only place its struct member is named.
type decisionFieldSpec struct {
	kind decisionFieldKind
	// groupTag, when non-zero, is a nesting marker the fingerprint encoder
	// emits immediately before this field, opening the subject, resource or
	// decision group exactly where the historical encoding placed it. The
	// archive has no group markers and ignores this.
	groupTag  fingerprintTag
	getString func(*DecisionRecord) string
	setString func(*DecisionRecord, string)
	getList   func(*DecisionRecord) []string
	setList   func(*DecisionRecord, []string)
	getBool   func(*DecisionRecord) bool
	setBool   func(*DecisionRecord, bool)
	getInt    func(*DecisionRecord) int
	setInt    func(*DecisionRecord, int)
}

// decisionFields lists every DecisionRecord leaf field in fingerprint
// canonical order, which the archive reproduces exactly. The subject group
// opens at Subject.ID, the resource group at Resource.ID and the decision
// group at Decision.Allowed, matching the historical nesting markers.
var decisionFields = [...]decisionFieldSpec{
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.SubjectOrg },
		setString: func(d *DecisionRecord, s string) { d.Request.SubjectOrg = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.ResourceOrg },
		setString: func(d *DecisionRecord, s string) { d.Request.ResourceOrg = s },
	},
	{
		kind:      decisionFieldString,
		groupTag:  tagSubject,
		getString: func(d *DecisionRecord) string { return d.Request.Subject.ID },
		setString: func(d *DecisionRecord, s string) { d.Request.Subject.ID = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Subject.Kind },
		setString: func(d *DecisionRecord, s string) { d.Request.Subject.Kind = s },
	},
	{
		kind:    decisionFieldStringList,
		getList: func(d *DecisionRecord) []string { return d.Request.Subject.Roles },
		setList: func(d *DecisionRecord, l []string) { d.Request.Subject.Roles = l },
	},
	{
		kind:    decisionFieldBool,
		getBool: func(d *DecisionRecord) bool { return d.Request.Subject.Disabled },
		setBool: func(d *DecisionRecord, v bool) { d.Request.Subject.Disabled = v },
	},
	{
		kind:      decisionFieldString,
		groupTag:  tagResource,
		getString: func(d *DecisionRecord) string { return d.Request.Resource.ID },
		setString: func(d *DecisionRecord, s string) { d.Request.Resource.ID = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Resource.Scope },
		setString: func(d *DecisionRecord, s string) { d.Request.Resource.Scope = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Action },
		setString: func(d *DecisionRecord, s string) { d.Request.Action = s },
	},
	{
		kind:     decisionFieldBool,
		groupTag: tagDecision,
		getBool:  func(d *DecisionRecord) bool { return d.Decision.Allowed },
		setBool:  func(d *DecisionRecord, v bool) { d.Decision.Allowed = v },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Decision.Reason },
		setString: func(d *DecisionRecord, s string) { d.Decision.Reason = s },
	},
	{
		kind:    decisionFieldStringList,
		getList: func(d *DecisionRecord) []string { return d.Decision.Matched },
		setList: func(d *DecisionRecord, l []string) { d.Decision.Matched = l },
	},
	{
		kind:   decisionFieldInt,
		getInt: func(d *DecisionRecord) int { return d.Decision.Version },
		setInt: func(d *DecisionRecord, v int) { d.Decision.Version = v },
	},
}

// decisionRecordHasNonUTF8 reports whether any string or list element of d
// carries bytes that are not valid UTF-8. It ranges the single field table,
// so its idea of which decision strings the fingerprint protects can never
// diverge from the fields the encoders write. Boolean and integer fields
// cannot carry a raw byte and are skipped by kind rather than listed
// separately.
func decisionRecordHasNonUTF8(d *DecisionRecord) bool {
	for i := range decisionFields {
		f := &decisionFields[i]
		switch f.kind {
		case decisionFieldString:
			if !utf8.ValidString(f.getString(d)) {
				return true
			}
		case decisionFieldStringList:
			for _, s := range f.getList(d) {
				if !utf8.ValidString(s) {
					return true
				}
			}
		}
	}
	return false
}

// cloneDecisionLists detaches every string list field of src into dst,
// preserving each list's nil-versus-empty shape. It ranges the single field
// table, so a list field added to the record is detached here without this
// function changing.
func cloneDecisionLists(dst, src *DecisionRecord) {
	for i := range decisionFields {
		f := &decisionFields[i]
		if f.kind == decisionFieldStringList {
			f.setList(dst, cloneStrings(f.getList(src)))
		}
	}
}

