61	// cloneExportedRecords deep-copies a record set so mutating any string
62	// field or roles/matched/policies slice in the copy never reaches the
63	// original. encoding/json cannot be used for this: it would "repair" the
64	// invalid bytes under test.
65	func cloneExportedRecords(in []AuditRecord) []AuditRecord {
66		out := make([]AuditRecord, len(in))
67		for i, r := range in {
68			cp := r
69			if r.Change != nil {
70				c := *r.Change
71				if r.Change.Policies != nil {
72					c.Policies = append([]Policy(nil), r.Change.Policies...)
73				}
74				cp.Change = &c
75			}
76			if r.Decision != nil {
77				d := *r.Decision
78				if r.Decision.Request.Subject.Roles != nil {
79					d.Request.Subject.Roles = append([]string(nil), r.Decision.Request.Subject.Roles...)
80				}
81				if r.Decision.Decision.Matched != nil {
82					d.Decision.Matched = append([]string(nil), r.Decision.Decision.Matched...)
83				}
84				cp.Decision = &d
85			}
86			out[i] = cp
87		}
88		return out
89	}
