91	// TestInvalidUTF8IsAcceptedAndPreservedByteForByte drives the live API
92	// with strings carrying invalid UTF-8 in every policy and request string
93	// reachable through the public surface. Acceptance must be unchanged, no
94	// byte may be deleted, replaced or normalized, and query/export/offline
95	// review must observe the exact submitted bytes.
96	func TestInvalidUTF8IsAcceptedAndPreservedByteForByte(t *testing.T) {
97		s := NewStore()
98		submitted := Policy{
99			ID:      "策" + invalidByte + "略",
100			Subject: "用" + invalidByte + "戶",
101			Action:  "读" + invalidByte,
