110		req := OrgRequest{
111			SubjectOrg:  "acme",
112			ResourceOrg: "acme",
113			Subject: Subject{
114				ID:    "用" + invalidByte + "戶",
115				Kind:  "外" + invalidByte + "部",
116				Roles: []string{"角" + invalidByte + "色", "普通角色"},
117			},
