119			Action:   submitted.Action,
120		}
121		d := s.Decide("acme", req)
122		if !d.Allowed || d.Version != 1 || d.Reason != "matched allow policy" {
123			t.Fatalf("decision on invalid-UTF-8 request = %+v", d)
124		}
125		if want := []string{submitted.ID}; !reflect.DeepEqual(d.Matched, want) {
126			t.Fatalf("matched = %q, want byte-exact %q", d.Matched, want)
127		}
