457				// Offline review must reject first: never a successful or
458				// "consistent" conclusion over tampered material.
459				if got, err := RecheckDecisionOffline(org, recs, cp, 2); !errors.Is(err, ErrInvalidRange) {
460					t.Fatalf("%s: RecheckDecisionOffline err = %v, review = %+v, want ErrInvalidRange", name, err, got)
461				}
462			}
463		}
464	}
465	
466	// replacementLabel names a substitution without relying on rendered
467	// output, which displays both cases as a replacement character.
468	func replacementLabel(s string) string {
469		switch s {
470		case anotherInvalidByte:
471			return "0xFE"
472		case replacementRune:
473			return "U+FFFD"
474		default:
475			return "?"
476		}
477	}
478	
479	// TestReplacementRuneIsGenuineContentToo separates three byte-different
480	// strings that displays may conflate: a lone 0xFF, a lone 0xFE, and a
481	// real U+FFFD rune. A record genuinely containing U+FFFD is valid UTF-8,
482	// verifies and keeps the legacy fingerprint; substituting any one for
483	// another is a content change.
484	func TestReplacementRuneIsGenuineContentToo(t *testing.T) {
485		s := NewStore()
486		policies := []Policy{{
487			ID:      "p-" + replacementRune + "-1",
488			Subject: "用" + replacementRune + "戶",
489			Action:  "read", Scope: "org/a", Effect: EffectAllow,
490		}}
491		s.Publish("acme", 0, policies)
492		req := request("acme", "用"+replacementRune+"戶", "r1", "org/a", "read")
493		d := s.Decide("acme", req)
494		if !d.Allowed {
495			t.Fatalf("request with genuine U+FFFD = %+v", d)
496		}
497		recs, cp, err := s.AuditExport("acme", 0)
498		if err != nil {
499			t.Fatal(err)
500		}
501		if err := VerifyAudit("acme", recs, cp); err != nil {
502			t.Fatalf("genuine U+FFFD must verify: %v", err)
503		}
504		if !utf8.ValidString(recs[0].Change.Policies[0].ID) {
505			t.Fatal("genuine U+FFFD must remain valid UTF-8")
506		}
507		if fingerprintFor(&recs[0]) != legacyJSONFingerprint(&recs[0]) {
508			t.Fatal("valid-UTF-8 U+FFFD record must keep the legacy JSON fingerprint")
509		}
510		if review, err := RecheckDecisionOffline("acme", recs, cp, 2); err != nil || !review.Consistent {
511			t.Fatalf("genuine U+FFFD review = %+v, %v", review, err)
512		}
513	
514		// Raw invalid bytes exported from the live API.
515		raw := NewStore()
516		raw.Publish("acme", 0, []Policy{{
517			ID: "p" + invalidByte, Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow,
518		}})
519		rawRecs, rawCP, err := raw.AuditExport("acme", 0)
520		if err != nil {
521			t.Fatal(err)
522		}
523		if err := VerifyAudit("acme", rawRecs, rawCP); err != nil {
524			t.Fatalf("raw-byte record must verify: %v", err)
525		}
526	
527		// Replace the raw byte with a genuine U+FFFD rune: content changed.
528		tampered := cloneExportedRecords(rawRecs)
529		tampered[0].Change.Policies[0].ID = "p" + replacementRune
530		if err := VerifyAudit("acme", tampered, rawCP); !errors.Is(err, ErrInvalidRange) {
531			t.Fatalf("raw 0xFF -> U+FFFD err = %v, want ErrInvalidRange", err)
532		}
533	
534		// The reverse substitution is also a change: the valid-UTF-8 record's
535		// real U+FFFD replaced by a lone 0xFF.
536		back := cloneExportedRecords(recs)
537		back[0].Change.Policies[0].ID = "p-" + invalidByte + "-1"
538		if err := VerifyAudit("acme", back, cp); !errors.Is(err, ErrInvalidRange) {
539			t.Fatalf("U+FFFD -> raw 0xFF err = %v, want ErrInvalidRange", err)
540		}
541	}
542	
543	// TestLegacyFingerprintsUnchangedForValidUTF8 proves byte-identical
544	// fingerprints for valid UTF-8 across policy changes, rollbacks,
545	// decisions, nil-vs-empty lists, and strings full of characters JSON
546	// escapes specially: Chinese, quotes, backslashes, control characters,
547	// angle/ampersand and a genuine replacement rune.
548	func TestLegacyFingerprintsUnchangedForValidUTF8(t *testing.T) {
549		org := "acme"
550		tricky := []Policy{{
551			ID:        "p\"1\\中\t\n\r<>&" + replacementRune,
552			Subject:   "主\"体\\",
553			Action:    "a\tb\nc",
554			Scope:     "org/中/区",
555			Effect:    EffectAllow,
556			Recursive: true,
557		}}
558		prev := genesisFingerprint(org)
559		records := []AuditRecord{
560			syntheticRecord(org, 1, AuditPolicyChange, &PolicyChange{
561				Version: 1, Policies: tricky,
562			}, nil, prev),
563		}
564		prev = records[0].Fingerprint
565		// Rollback carrying a nil policy set.
566		records = append(records, syntheticRecord(org, 2, AuditPolicyChange, &PolicyChange{
567			Version: 2, Policies: nil, SourceVersion: 1, RolledBack: true,
568		}, nil, prev))
569		prev = records[1].Fingerprint
570		// Decision with nil roles and nil matched lists.
571		records = append(records, syntheticRecord(org, 3, AuditDecision, nil, &DecisionRecord{
572			Request: OrgRequest{
573				SubjectOrg:  org,
574				ResourceOrg: org,
575				Subject:     Subject{ID: "身\"份\\中"},
576				Resource:    Resource{ID: "r\"1", Scope: "org/中/区"},
577				Action:      "a\tb",
578			},
579			Decision: Decision{Allowed: true, Reason: "理\"由\n中", Version: 2},
580		}, prev))
581		prev = records[2].Fingerprint
582		// Decision with explicitly empty (non-nil) lists.
583		records = append(records, syntheticRecord(org, 4, AuditDecision, nil, &DecisionRecord{
584			Request: OrgRequest{
585				SubjectOrg:  org,
586				ResourceOrg: org,
587				Subject:     Subject{ID: "u2", Roles: []string{}},
588				Resource:    Resource{ID: "r2", Scope: "org/a"},
589				Action:      "read",
590			},
591			Decision: Decision{Allowed: false, Reason: "no matching allow policy", Matched: []string{}, Version: 2},
592		}, prev))
593	
594		for i := range records {
595			r := &records[i]
596			if got := fingerprintFor(r); got != legacyJSONFingerprint(r) {
597				t.Fatalf("record %d fingerprint drifted from the legacy JSON encoding", r.Seq)
598			}
599		}
600		cp := Checkpoint{Org: org, EndSeq: len(records), Fingerprint: records[len(records)-1].Fingerprint}
601		if err := VerifyAudit(org, records, cp); err != nil {
602			t.Fatalf("legacy-compatible chain must verify: %v", err)
603		}
604	
605		// Sanity: an invalid byte makes the same shape leave the JSON family.
606		raw := syntheticRecord(org, 5, AuditDecision, nil, &DecisionRecord{
607			Request:  request(org, "u"+invalidByte, "r1", "org/a", "read"),
608			Decision: Decision{Allowed: false, Reason: "x", Version: 2},
609		}, cp.Fingerprint)
610		if fingerprintFor(&raw) == legacyJSONFingerprint(&raw) {
611			t.Fatal("invalid-byte envelope unexpectedly shares the JSON fingerprint")
612		}
613	}
