303	// archiveMagicV1 mirrors the darksafe package's stable framing prefix; the
304	// format is explicitly versioned (…-v1), so the CLI test relies only on its
305	// published layout.
306	const archiveMagicV1 = "darksafe-audit-archive-v1\n"
307	
308	// reframeArchive parses one archive frame, lets mutate alter the payload in
309	// place, and rebuilds a frame with a consistent declared length and
310	// checksum, so a test can tamper content without tripping framing/checksum
311	// checks and reach the library's whole-chain validation.
312	func reframeArchive(t *testing.T, data []byte, mutate func(payload []byte)) []byte {
313		t.Helper()
314		magicLen := len(archiveMagicV1)
315		n := int(binary.BigEndian.Uint32(data[magicLen : magicLen+4]))
316		payload := append([]byte(nil), data[magicLen+4:magicLen+4+n]...)
317		mutate(payload)
318		out := append([]byte(nil), archiveMagicV1...)
319		var lb [4]byte
320		binary.BigEndian.PutUint32(lb[:], uint32(len(payload)))
321		out = append(out, lb[:]...)
322		out = append(out, payload...)
323		sum := sha256.Sum256(payload)
324		return append(out, sum[:]...)
325	}
